def normalize_mean(X):
    """Global mean normalization — what the old inference script does."""
    scale = np.mean(np.abs(X)) + 1e-6
    return X / scale


def normalize_raw(X):
    """No normalization — matches training pipeline."""
    return X.copy()


def predict(model, X):
    """Run model predictions in batches."""
    preds = model.predict(X, verbose=0, batch_size=256).reshape(-1)
    return preds

